package com.lbos.commercecustomer.service.impl; import com.lbos.commercecustomer.dto.request.ReplaceWishlistProductRequest;import com.lbos.commercecustomer.dto.response.*;import com.lbos.commercecustomer.entity.*;import com.lbos.commercecustomer.enums.ProductStatus;import com.lbos.commercecustomer.exception.*;import com.lbos.commercecustomer.mapper.CommerceMapper;import com.lbos.commercecustomer.repository.*;import com.lbos.commercecustomer.service.WishlistService;import java.util.*;import org.springframework.data.domain.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.*; @Service public class WishlistServiceImpl implements WishlistService {private final CustomerWishlistItemRepository repo;private final ProductRepository products;private final ContextSupport ctx;private final CommerceMapper map;private final RetailerEnrichmentSupport retailers;public WishlistServiceImpl(CustomerWishlistItemRepository r,ProductRepository p,ContextSupport c,CommerceMapper m,RetailerEnrichmentSupport e){repo=r;products=p;ctx=c;map=m;retailers=e;}private WishlistResponse dto(CustomerWishlistItem wishlistItem){return new WishlistResponse(wishlistItem.getId(),map.product(wishlistItem.getProduct(),retailers.resolveOne(wishlistItem.getProduct().getRetailerId())),wishlistItem.getCreatedAt());}private WishlistResponse dto(CustomerWishlistItem wishlistItem,Map<UUID,com.lbos.commercecustomer.dto.client.partner.RetailerSummaryResponse> retailerById){return new WishlistResponse(wishlistItem.getId(),map.product(wishlistItem.getProduct(),retailerById.get(wishlistItem.getProduct().getRetailerId())),wishlistItem.getCreatedAt());}private CustomerWishlistItem owned(UUID id){var customer=ctx.customer();return repo.findByIdAndCustomerId(id,customer.getId()).orElseThrow(()->new ResourceNotFoundException("Wishlist item not found"));}@Transactional public WishlistResponse add(ReplaceWishlistProductRequest r){var customer=ctx.customer();if(repo.existsByCustomerIdAndProductId(customer.getId(),r.productId()))throw new DuplicateResourceException("Product already wishlisted");var wishlistItem=new CustomerWishlistItem();wishlistItem.setCustomer(customer);wishlistItem.setProduct(products.findById(r.productId()).orElseThrow(()->new ResourceNotFoundException("Product not found")));return dto(repo.save(wishlistItem));}@Transactional(readOnly=true) public WishlistResponse get(UUID id){return dto(owned(id));}
  /** Retailer summaries for the page's distinct products are resolved once up front, same
   * reasoning as ProductDiscoveryServiceImpl.search() - a wishlist page is a product listing
   * too, and must show each item's shop just like Home/Search/Category. */
  @Transactional(readOnly=true) public PageResponse<WishlistResponse> list(int p,int z){var wishlistPage=repo.findByCustomerId(ctx.customer().getId(),PageRequest.of(p,z,Sort.by(Sort.Direction.DESC,"createdAt")));var retailerById=retailers.resolve(wishlistPage.getContent().stream().map(CustomerWishlistItem::getProduct).toList());return new PageResponse<>(wishlistPage.map(item->dto(item,retailerById)).getContent(),p,z,wishlistPage.getTotalElements(),wishlistPage.getTotalPages());}@Transactional public WishlistResponse replace(UUID id,ReplaceWishlistProductRequest r){var wishlistItem=owned(id);if(repo.existsByCustomerIdAndProductId(wishlistItem.getCustomer().getId(),r.productId()))throw new DuplicateResourceException("Product already wishlisted");wishlistItem.setProduct(products.findById(r.productId()).orElseThrow(()->new ResourceNotFoundException("Product not found")));return dto(repo.save(wishlistItem));}@Transactional public void delete(UUID id){repo.delete(owned(id));}@Transactional(readOnly=true) public WishlistSummaryResponse summary(){var wishlistItems=repo.findByCustomerId(ctx.customer().getId(),Pageable.unpaged()).getContent();return new WishlistSummaryResponse(wishlistItems.size(),wishlistItems.stream().filter(item->ProductStatus.ACTIVE.equals(item.getProduct().getStatus())&&item.getProduct().getStock()>0).count(),wishlistItems.stream().filter(item->item.getProduct().getStock()==0).count());}@Transactional(readOnly=true) public Map<Long,Boolean> membership(List<Long> ids){var customer=ctx.customer();var wishlisted=new HashSet<>(repo.findProductIdsByCustomerIdAndProductIdIn(customer.getId(),ids));var membershipByProductId=new HashMap<Long,Boolean>();ids.forEach(productId->membershipByProductId.put(productId,wishlisted.contains(productId)));return membershipByProductId;}}